image.asymptote:
// 3-D interactive (WebGL) figure.
import graph3; size(10cm); currentprojection=orthographic(5,2.3,2.6);
real f(pair p){return 1.6+0.35*sin(1.1*p.x)-0.12*(p.y-1.5)^2;}
real L=3;
draw(surface((0,0,0)--(L,0,0)--(L,L,0)--(0,L,0)--cycle), gray(0.85)+opacity(0.6));
for(int i=0;i<=3;++i){ draw((i,0,0)--(i,L,0), gray(0.5)+0.3pt); draw((0,i,0)--(L,i,0), gray(0.5)+0.3pt); }
label("parameter domain $(u,v)$", (L/2,L+0.4,0), gray(0.3));
surface s=surface(f,(0,0),(L,L),28,28);
draw(s, rgb(0.6,0.78,0.95)+opacity(0.5));
for(int i=0;i<=3;++i){
  path3 uc=graph(new triple(real u){return (u,i,f((u,i)));},0,L,40,operator ..); draw(uc, blue+0.7pt);
  path3 vc=graph(new triple(real v){return (i,v,f((i,v)));},0,L,40,operator ..); draw(vc, red+0.7pt);
}
label("surface $S$", (L/2,L+0.4,f((L/2,L))+0.2));
draw((L/2,L/2,0.08)--(L/2,L/2,f((L/2,L/2))-0.12), black+1pt, Arrow3);
label("$T$", (L/2,L/2,f((L/2,L/2))/2), 2E);
draw(O--(L+0.7,0,0),gray,Arrow3); draw(O--(0,L+0.9,0),gray,Arrow3); draw(O--(0,0,2.4),gray,Arrow3);
label("$x$",(L+0.7,0,0),S); label("$y$",(0,L+0.9,0),E); label("$z$",(0,0,2.4),N);

        // 3-D interactive (WebGL) figure.
        import graph3;
        size(8cm);
        currentprojection=orthographic(5,3,2.6);

        real a=1.4, h=2.6;
        surface cyl=surface(new triple(pair t){return (a*cos(t.x), a*sin(t.x), t.y);},(0,0),(2pi,h),40,12);
        draw(cyl, rgb(0.70,0.78,0.90)+opacity(0.55), meshpen=rgb(0.45,0.5,0.65)+linewidth(0.15pt));
        draw(circle((0,0,h),a,(0,0,1)), black+linewidth(0.7pt));

        real th=35*pi/180, zP=1.7;
        triple P=(a*cos(th), a*sin(th), zP);
        triple rtheta=1.1*(-sin(th), cos(th), 0);   // d r / d theta  (around the circle)
        triple rz=(0,0,1.1);                          // d r / d z      (up the axis)
        triple n=1.1*(cos(th), sin(th), 0);           // r_theta x r_z  = outward radial normal

        draw(P--(P+rtheta), blue+linewidth(1.4pt), Arrow3);
        draw(P--(P+rz),     deepgreen+linewidth(1.4pt), Arrow3);
        draw(P--(P+n),      red+linewidth(1.4pt), Arrow3);
        label("$\mathbf r_\theta$", P+rtheta, NW);
        label("$\mathbf r_z$", P+rz, N);
        label("$\mathbf r_\theta\times\mathbf r_z$", P+n, E);
        dot(P); label("$P$", P, SW);

        draw(O--(2.4,0,0), gray, Arrow3); draw(O--(0,2.4,0), gray, Arrow3); draw(O--(0,0,3.2), gray, Arrow3);
        label("$x$",(2.4,0,0),S); label("$y$",(0,2.4,0),E); label("$z$",(0,0,3.2),N);

subsection.p:
If g has continuous first partial derivatives, its graph z=g(x,y) is a smooth surface. It has the natural parametrization \boxed{ \mathbf r(x,y)=(x,y,g(x,y)). } The two tangent vectors are \mathbf r_x=(1,0,g_x), \qquad \mathbf r_y=(0,1,g_y). Their cross product is
\mathbf r_x\times \mathbf r_y \amp= (-g_x,-g_y,1).
So a normal vector to the graph is \boxed{ (-g_x,-g_y,1). }
